package com.blog.security; import com.blog.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class BlogUserDetailsService implements UserDetailsService { private final UserRepository users; public UserDetails loadUserByUsername(String email){var u=users.findByEmail(email).orElseThrow(()->new UsernameNotFoundException("User not found"));return new org.springframework.security.core.userdetails.User(u.getEmail(),u.getPassword(),java.util.List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name())));}}
